import type {IncomingMessage, ConversationCursor} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = messageValidators[message.type];
  return validator ? validator(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

const messageValidators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  ['user_message']: validateUserMessage,
  ping: validatePingMessage,
  ['list_sessions']: validateListSessionsMessage,
  ['list_conversations']: validateListConversationsMessage,
};

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if (isInvalidConversationLimit(limit)) {
    return {valid: false, error: 'list_conversations limit must be an integer from 1 to 200'};
  }

  if (message.before === undefined)
    return {valid: true, data: {type: 'list_conversations', limit: limit as number | undefined}};
  if (!isObject(message.before)) {
    return {valid: false, error: 'list_conversations before must be an object'};
  }

  const before = message.before as Record<string, unknown>;
  if (!isValidSessionId(before.sessionId)) {
    return {valid: false, error: 'list_conversations before.sessionId must be 1-128 characters'};
  }
  if (typeof before.updatedAt !== 'string' || !Number.isFinite(Date.parse(before.updatedAt))) {
    return {valid: false, error: 'list_conversations before.updatedAt must be a valid date'};
  }

  const cursor: ConversationCursor = {sessionId: before.sessionId, updatedAt: before.updatedAt};
  return {valid: true, data: {type: 'list_conversations', limit: limit as number | undefined, before: cursor}};
}

function isInvalidConversationLimit(value: unknown): boolean {
  return value !== undefined && (!Number.isInteger(value) || Number(value) < 1 || Number(value) > 200);
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isValidSessionId(value: unknown): value is string {
  return typeof value === 'string' && value.length >= 1 && value.length <= 128;
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit as number | undefined;
  if (limit !== undefined && (!Number.isInteger(limit) || limit < 0)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  if (message.before === undefined) {
    return {valid: true, data: {type: 'list_sessions', limit}};
  }

  if (!isObject(message.before)) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }

  const before = message.before as Record<string, unknown>;
  if (!isValidSessionId(before.sessionId)) {
    return {valid: false, error: 'list_sessions before.sessionId must be 1-128 characters'};
  }

  const updatedAt = before.updatedAt;
  if (!isValidCursorDate(updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid date'};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      limit,
      before: {sessionId: before.sessionId, updatedAt: updatedAt as string | number},
    },
  };
}

function isValidCursorDate(value: unknown): value is string | number {
  if (typeof value === 'string') return Number.isFinite(Date.parse(value));
  return typeof value === 'number' && Number.isFinite(value);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}
import type {SessionEntry} from './session.js';
import type {SessionCursor} from './sessionStore.js';

export interface UserMessagePayload {
  type: 'user_message';
  content: string;
}

export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export interface ListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: SessionCursor;
}

export interface ConversationCursor {
  updatedAt: string;
  sessionId: string;
}

export interface ListConversationsMessage {
  type: 'list_conversations';
  limit?: number;
  before?: ConversationCursor;
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage | ListConversationsMessage;

export interface ConnectedMessage {
  type: 'connected';
  sessionId: string;
  message: string;
  examplePrompts: string[];
  resumed?: boolean;
  entryCount?: number;
  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
  resumeFailure?: 'expired' | 'unknown';
}

export interface EntryUpsertMessage {
  type: 'entry_upsert';
  index: number;
  entry: SessionEntry;
}

export interface EntryDeltaMessage {
  type: 'entry_delta';
  index: number;
  delta: string;
}

export interface EntryCommitMessage {
  type: 'entry_commit';
  index: number;
}

export interface ErrorMessage {
  type: 'error';
  code: string;
  message: string;
}

export interface PongMessage {
  type: 'pong';
  timestamp: number;
}

export interface EntrySkipMessage {
  type: 'entry_skip';
  index: number;
}

export interface StreamEndMessage {
  type: 'stream_end';
}

export interface SessionSummaryFrame {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

export interface SessionListMessage {
  type: 'session_list';
  sessions: SessionSummaryFrame[];
}

export interface ConversationSummary {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

export interface ConversationListMessage {
  type: 'conversation_list';
  conversations: ConversationSummary[];
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage
  | SessionListMessage
  | ConversationListMessage;

export {ErrorCodes} from './session.js';

